content:
.repository-page{max-width:1380px}
.repository-hero{padding:4rem 0 1.6rem}
.repository-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:2rem}
.repository-heading h1{font-size:clamp(2rem,5vw,3.4rem);line-height:1.05;margin:.5rem 0 1rem}
.repository-heading p{max-width:70ch;margin:0}
.repository-meta{margin-top:1.25rem;color:var(--muted);font-size:.9rem}
.repository-browser{padding:.75rem 0 4rem}
.browser-toolbar{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;padding:1rem 1.2rem;border:1px solid rgba(148,163,184,.18);border-bottom:0;border-radius:var(--radius) var(--radius) 0 0;background:rgba(18,18,37,.84)}
.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:.72rem;color:var(--muted);margin:0 0 .35rem;font-weight:700}
.breadcrumbs{font-size:.94rem;word-break:break-word}
.breadcrumbs button{appearance:none;border:0;padding:0;background:none;color:var(--primary);font:inherit;cursor:pointer}
.breadcrumbs button:hover{text-decoration:underline}
.breadcrumbs span{color:var(--text)}
.github-file-link{font-size:.85rem;white-space:nowrap}
.browser-layout{display:grid;grid-template-columns:minmax(240px,320px) minmax(0,1fr);min-height:590px;border:1px solid rgba(148,163,184,.18);border-radius:0 0 var(--radius) var(--radius);overflow:hidden;background:var(--card);box-shadow:var(--shadow)}
.repository-navigation{border-right:1px solid rgba(148,163,184,.18);background:rgba(11,11,20,.5);min-width:0}
.parent-link{width:100%;padding:.8rem 1rem;border:0;border-bottom:1px solid rgba(148,163,184,.14);text-align:left;background:rgba(139,92,246,.07);color:var(--primary);cursor:pointer;font:inherit}
.browser-status{padding:1.4rem;color:var(--muted)}
.directory-list{list-style:none;margin:0;padding:.35rem 0}
.directory-entry{display:grid;grid-template-columns:1.25rem minmax(0,1fr) auto;align-items:center;gap:.55rem;width:100%;padding:.68rem 1rem;border:0;background:transparent;color:var(--text);font:inherit;text-align:left;cursor:pointer}
.directory-entry:hover,.directory-entry:focus-visible{background:rgba(139,92,246,.12);outline:none}
.entry-icon{color:var(--muted);font-family:ui-monospace,monospace;font-weight:700}
.entry-icon.directory{color:var(--primary)}
.entry-detail{color:var(--muted);font-size:.72rem}
.file-panel{min-width:0;background:#0d0e1b;overflow:hidden}
.file-header{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.85rem 1rem;border-bottom:1px solid rgba(148,163,184,.16);background:rgba(18,18,37,.9)}
.file-header h2{font-size:.9rem;margin:0;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}
.file-header span{font-size:.75rem;color:var(--muted);white-space:nowrap}
.empty-state,.file-loading{display:grid;place-items:center;align-content:center;text-align:center;min-height:400px;padding:2rem;color:var(--muted)}
.empty-state h2{color:var(--text);margin:.5rem 0 0}
.empty-state p{max-width:38ch}
.empty-icon{font-size:2.4rem;color:var(--primary)}
.spinner{width:24px;height:24px;border:2px solid rgba(148,163,184,.25);border-top-color:var(--primary);border-radius:50%;animation:spin .8s linear infinite;margin-bottom:.75rem}
@keyframes spin{to{transform:rotate(360deg)}}
.code-scroller{overflow:auto;max-height:72vh;overscroll-behavior:contain;background:#0d0e1b}
.code-table{border-collapse:collapse;width:max-content;min-width:100%;font:13px/1.55 ui-monospace,SFMono-Regular,Consolas,"Liberation Mono",monospace}
.code-table td{padding:0;border:0;vertical-align:top}
.line-number{position:sticky;left:0;width:1%;min-width:3.5rem;padding:0 .9rem!important;text-align:right;color:#697386;user-select:none;background:#0d0e1b;border-right:1px solid rgba(148,163,184,.1)!important}
.line-code{padding:0 1rem!important;white-space:pre;background:transparent!important;min-height:1.55em}
.markdown-body{padding:clamp(1.2rem,4vw,2.5rem);max-width:860px;color:#d8dce5;overflow-wrap:anywhere}
.markdown-body h1,.markdown-body h2,.markdown-body h3{line-height:1.25;color:var(--text);margin-top:1.6em}
.markdown-body h1:first-child{margin-top:0}
.markdown-body h1,.markdown-body h2{padding-bottom:.45rem;border-bottom:1px solid rgba(148,163,184,.16)}
.markdown-body pre{overflow:auto;padding:1rem;border-radius:12px;background:#090a13;border:1px solid rgba(148,163,184,.13)}
.markdown-body code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;background:rgba(148,163,184,.12);padding:.12em .3em;border-radius:5px}
.markdown-body pre code{padding:0;background:transparent}
.markdown-body table{display:block;max-width:100%;overflow:auto;border-collapse:collapse}
.markdown-body th,.markdown-body td{padding:.55rem .8rem;border:1px solid rgba(148,163,184,.2)}
.markdown-body img{max-width:100%;height:auto}
:focus-visible{outline:3px solid var(--primary);outline-offset:3px}
@media (max-width:880px){
  .repository-hero{padding-top:2.7rem}
  .repository-heading,.browser-toolbar{align-items:flex-start;flex-direction:column}
  .browser-layout{grid-template-columns:1fr}
  .repository-navigation{border-right:0;border-bottom:1px solid rgba(148,163,184,.18);max-height:360px;overflow:auto}
  .github-file-link{white-space:normal}
  .file-panel{min-height:420px}
}
@media (max-width:520px){
  .repository-heading .btn{width:100%;justify-content:center}
  .browser-toolbar{padding:.85rem}
  .directory-entry{padding:.7rem .8rem}
  .entry-detail{display:none}
}
@media (prefers-reduced-motion:reduce){.spinner{animation:none}}
